    self,
    session: TmuxSession,
    trial_handler: TrialHandler,
    agent: BaseAgent,
) -> tuple[AgentResult | None, FailureMode]:
    if self._global_agent_timeout_sec:
        agent_timeout_sec = self._global_agent_timeout_sec
    else:
        agent_timeout_sec = (
            trial_handler.task.max_agent_timeout_sec
            * self._global_timeout_multiplier
        )

    try:
        result = asyncio.run(
            self._run_agent_with_timeout(
                trial_handler=trial_handler,
                session=session,
                logging_dir=trial_handler.trial_paths.agent_logging_dir,
                timeout_sec=agent_timeout_sec,
                agent=agent,
            )
        )
        if result is None:
            return None, FailureMode.UNKNOWN_AGENT_ERROR

        return result, result.failure_mode

    except asyncio.TimeoutError:
        self._logger.warning(
            f"Agent timed out after "
            f"{agent_timeout_sec}s for task "
            f"{trial_handler.task_id}."
        )

        partial_result = AgentResult(
            failure_mode=FailureMode.AGENT_TIMEOUT,
            timestamped_markers=getattr(agent, "_timestamped_markers", []),
        )
        return partial_result, FailureMode.AGENT_TIMEOUT

    except RetryError as e:
        last_exception = e.last_attempt.exception()
        if isinstance(last_exception, ContextLengthExceededError):
            self._logger.error(
                f"Context length exceeded for task {trial_handler.task_id}: "
                f"{last_exception}"

"""Shared bench agent-timeout policy (issue #1122).

The bench cap stops being a flat guillotine: the base cap is configurable
per run and, when extension is enabled, the kill deadline recedes while
the agent provably makes progress — growth of its rendered output (deltas,
tool calls, tool results). A silent agent dies at the base cap exactly as
before; an agent that never stops producing dies only at a hard ceiling.

bench/terminal_bench/fa_agent.py and bench/harbor_fa/fa_agent.py both
import this module so legacy and 4.0 measurement policy cannot drift.

Environment knobs (all optional; empty string counts as absent, so a
default workflow run keeps today's byte-for-byte behavior):
  FA_AGENT_TIMEOUT_SEC         base cap seconds (default 360)
  FA_PROGRESS_EXTENSION        1/true/yes/on to enable progress-aware extension
  FA_AGENT_IDLE_WINDOW_SEC     silence span that constitutes a stall (default 120)
  FA_AGENT_CEILING_MULTIPLIER  hard ceiling = base * this (default 4)

Extension signal (E1): the counters fed to ProgressLadder measure the
agent process's own output bytes. The harness itself emits nothing into
that stream on a timer, so a pure keep-alive source does not exist here;
fa headless output is exactly deltas/tool activity.

All times are SECONDS ELAPSED since the agent phase started — no clocks
live in this module, so the ladder is deterministic and unit-testable.
"""

from __future__ import annotations

import math
import os
from dataclasses import dataclass, field

_BASE_DEFAULT = 360.0
_IDLE_DEFAULT = 120.0
_CEILING_DEFAULT = 4.0

_STALL = "stall"
_HARD_CEILING = "hard-ceiling"


def _optional(env, name):
    value = env.get(name)
    if value is None or value.strip() == "":
        return None
    return value.strip()


def _number(env, name, default):
    raw = _optional(env, name)
    if raw is None:
        return default
    try:
        value = float(raw)
    except ValueError:
        raise ValueError(
            f"{name} must be a number of seconds, got: {raw!r}"
        ) from None
    if not math.isfinite(value) or value <= 0:
        raise ValueError(f"{name} must be a finite positive number, got: {raw!r}")
    return value


def _flag(env, name, default=False):
    raw = _optional(env, name)
    if raw is None:
        return default
    return raw.lower() in ("1", "true", "yes", "on")


@dataclass(frozen=True)
class TimeoutKnobs:
    """Resolved knob values; from_env returns None when no knob is set."""

    base_sec: float = _BASE_DEFAULT
    progress_extension: bool = False
    idle_window_sec: float = _IDLE_DEFAULT
    ceiling_multiplier: float = _CEILING_DEFAULT

    @property
    def ceiling_sec(self) -> float:
        return self.base_sec * self.ceiling_multiplier

    @classmethod
    def from_env(cls, env=None) -> "TimeoutKnobs | None":
        env = os.environ if env is None else env
        if not any(
            _optional(env, name) is not None
            for name in (
                "FA_AGENT_TIMEOUT_SEC",
                "FA_PROGRESS_EXTENSION",
                "FA_AGENT_IDLE_WINDOW_SEC",
                "FA_AGENT_CEILING_MULTIPLIER",
            )
        ):
            return None
        return cls(
            base_sec=_number(env, "FA_AGENT_TIMEOUT_SEC", _BASE_DEFAULT),
            progress_extension=_flag(env, "FA_PROGRESS_EXTENSION"),
            idle_window_sec=_number(env, "FA_AGENT_IDLE_WINDOW_SEC", _IDLE_DEFAULT),
            ceiling_multiplier=_number(
                env, "FA_AGENT_CEILING_MULTIPLIER", _CEILING_DEFAULT
            ),
        )


@dataclass
class ProgressLadder:
    """Kill-decision state machine over (elapsed, output-bytes) samples.

    Deadline = max(base, last_progress + idle_window), capped at the hard
    ceiling. With extension disabled the deadline is the flat base cap —
    the regression pin: a silent agent dies at the base cap exactly as
    today. Every progress-driven deadline push is recorded in `events`
    for the run-metadata audit trail.
    """

    knobs: TimeoutKnobs
    last_progress_at: float = 0.0
    last_bytes: int = 0
    kill_at: float = 0.0
    events: list = field(default_factory=list)

    def __post_init__(self):
        # The standing deadline starts at the base cap — the regression pin:
        # a fully silent agent dies exactly at today's flat cap, even when
        # the idle window is larger than the base.
        self.kill_at = self.knobs.base_sec

    def _deadline_from(self, progress_elapsed: float) -> float:
        if not self.knobs.progress_extension:
            return self.knobs.base_sec
        target = max(
            self.knobs.base_sec, progress_elapsed + self.knobs.idle_window_sec
        )
        return min(target, self.knobs.ceiling_sec)

    def evaluate(self, elapsed: float, output_bytes: int | None = None):
        """Feed one sample; None = keep going, else 'stall' | 'hard-ceiling'.

        output_bytes None means the sample could not be read this poll —
        the ladder keeps its previous notion of progress.
        """
        if output_bytes is not None and output_bytes > self.last_bytes:
            self.last_bytes = output_bytes
            if elapsed > self.last_progress_at:
                new_deadline = self._deadline_from(elapsed)
                if new_deadline > self.kill_at:
                    self.events.append(
                        {
                            "at_sec": round(elapsed, 3),
                            "output_bytes": self.last_bytes,
                            "deadline_sec": round(new_deadline, 3),
                        }
                    )
                    self.kill_at = new_deadline
            self.last_progress_at = elapsed
        if elapsed < self.kill_at:
            return None
        if self.kill_at >= self.knobs.ceiling_sec and self.ceiling_is_extension():
            return _HARD_CEILING
        return _STALL

    def ceiling_is_extension(self) -> bool:
        return self.knobs.ceiling_sec > self.knobs.base_sec


def audit_dict(knobs: TimeoutKnobs, ladder: ProgressLadder, outcome: str | None):
    """Trial-artifact audit record (what extended, when, why)."""
    return {
        "issue": 1122,
        "policy": "progress-aware" if knobs.progress_extension else "flat-cap",
        "outcome": outcome or "completed",
        "knobs": {
            "base_sec": knobs.base_sec,
            "progress_extension": knobs.progress_extension,
            "idle_window_sec": knobs.idle_window_sec,
            "ceiling_multiplier": knobs.ceiling_multiplier,
            "ceiling_sec": knobs.ceiling_sec,
        },
        "last_progress_sec": round(ladder.last_progress_at, 3),
        "last_output_bytes": ladder.last_bytes,
        "deadline_sec": round(ladder.kill_at, 3),
        "extensions": ladder.events,
    }

"""Terminal-Bench adapter for the `fa` coding agent (flutter_agent_harness).

Follows the AbstractInstalledAgent pattern (same as the claude-code agent):
a setup script installs fa inside the task container, and the agent runs as
`fa -p "<instruction>"` in the container's tmux session, so fa's bash/read/
write tools operate on the container filesystem.

Host-side inputs (environment):
  FA_BUNDLE_TARBALL      tar.gz of a `dart build cli` bundle (bin/fah + lib/),
                         extracted to /opt/fa by the setup script.
  FA_PROVIDER_TYPE       provider kind (default: anthropic).
  FA_PROVIDER_CONFIG     JSON {"baseUrl": ..., "model": ..., "apiKeyEnvVar": ...}
                         (or FA_PROVIDER_CONFIG_BASE64).
  <apiKeyEnvVar>         the API key itself, e.g. ANTHROPIC_API_KEY.

  Timeout knobs (issue #1122, see bench/fa_agent_timeout.py): when any
  FA_AGENT_TIMEOUT_SEC / FA_PROGRESS_EXTENSION / FA_AGENT_IDLE_WINDOW_SEC /
  FA_AGENT_CEILING_MULTIPLIER is set, perform_task takes over the outer
  agent deadline from the harness's flat wait_for: the agent runs under a
  progress-aware ladder (silent => die at the base cap as today; output
  flowing => deadline recedes up to the hard ceiling). With no knobs set
  this module delegates to the stock AbstractInstalledAgent.perform_task
  byte-for-byte (historical comparability, issue #1122 REG-1).

  PYTHONPATH=bench/terminal_bench tb run -d terminal-bench-core==0.1.1 \
    --agent-import-path fa_agent:FaAgent -t hello-world
"""

import base64
import json
import os
import shlex
import sys
import tarfile
import threading
import time
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

import fa_agent_timeout as _timeout

from terminal_bench.agents.base_agent import AgentResult
from terminal_bench.agents.failure_mode import FailureMode
from terminal_bench.agents.installed_agents.abstract_installed_agent import (
    AbstractInstalledAgent,
)
from terminal_bench.terminal.models import TerminalCommand

_VERSION = "0.1.0"

# Host-side pane tap: tmux pipe-pane mirrors the pane stream (the agent's
# rendered deltas/tool output) into this file; its byte size is the
# progress signal. The harness emits nothing into the pane on a timer, so
# there is no keep-alive noise (issue #1122 E1).
_PROGRESS_LOG = "/tmp/fa-progress.log"
_POLL_SEC = 5.0


class FaAgent(AbstractInstalledAgent):
    @staticmethod
    def name() -> str:
        return "fa"

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._bundle_tarball = Path(
            os.environ.get("FA_BUNDLE_TARBALL", "fa-bundle.tar.gz")
        )
        if not self._bundle_tarball.is_file():
            raise FileNotFoundError(
                f"fa bundle tarball not found: {self._bundle_tarball} — build it "
                f"with bench/terminal_bench/run.sh"
            )

    @property
    def version(self) -> str:
        return self._version or _VERSION

    @property
    def _env(self) -> dict[str, str]:
        # Everything is passed base64-encoded: AbstractInstalledAgent emits
        # `export K='v'` lines, and base64 keeps arbitrary JSON/keys safe.
        env = {
            "FA_PROVIDER_TYPE": os.environ.get("FA_PROVIDER_TYPE", "anthropic"),
            "FA_PROVIDER_CONFIG_BASE64": _b64(os.environ["FA_PROVIDER_CONFIG"]),
        }
        key_var = json.loads(os.environ["FA_PROVIDER_CONFIG"]).get("apiKeyEnvVar")
        if key_var and os.environ.get(key_var):
            env[f"{key_var}_BASE64"] = _b64(os.environ[key_var])
        return env

    @property
    def _install_agent_script_path(self) -> Path:
        return self._get_templated_script_path("fa-setup.sh.j2")

    def perform_task(
        self,
        instruction: str,
        session,
        logging_dir=None,
    ):
        session.copy_to_container(
            self._bundle_tarball,
            container_dir="/installed-agent",
        )
        knobs = _timeout.TimeoutKnobs.from_env()
        if knobs is None:
            return super().perform_task(instruction, session, logging_dir)
        return self._perform_task_with_deadline(
            knobs, instruction, session, logging_dir
        )

    def _perform_task_with_deadline(self, knobs, instruction, session, logging_dir):
        """Stock perform_task under the issue #1122 deadline ladder.

        The stock body runs in a worker thread exactly as the harness would
        call it; this thread watches the pane-tap byte counter and, when the
        ladder says the run is stuck (or at the hard ceiling), interrupts the
        agent and returns an AGENT_TIMEOUT result — same failure mode the
        harness's own wait_for produces, but decided by the ladder. On
        natural completion the stock result passes through untouched.
        """
        base_perform = super().perform_task
        box = {}

        def _run_stock():
            try:
                box["result"] = base_perform(
                    instruction=instruction, session=session, logging_dir=logging_dir
                )
            except BaseException as exc:  # noqa: BLE001 - re-raised below
                box["error"] = exc

        worker = threading.Thread(target=_run_stock, daemon=True, name="fa-agent")
        self._tap_pane(session, on=True)
        worker.start()

        ladder = _timeout.ProgressLadder(knobs)
        start = time.monotonic()
        outcome = None
        while worker.is_alive():
            remaining = ladder.kill_at - (time.monotonic() - start)
            time.sleep(min(_POLL_SEC, max(remaining, 0.05)))
            outcome = ladder.evaluate(
                time.monotonic() - start, self._progress_bytes(session)
            )
            if outcome:
                session.send_keys(["C-c"], block=False, min_timeout_sec=0.5)
                worker.join(15)
                if worker.is_alive():
                    # fa ignored SIGINT (or the shell wedged): kill it from
                    # outside so the pane is free for the harness's tests.
                    session.container.exec_run(
                        ["sh", "-c", "pkill -f 'fa --session-root' || true"]
                    )
                    worker.join(30)
                break

        self._tap_pane(session, on=False)
        crashed = "error" in box
        if logging_dir is not None:
            self._write_audit(
                logging_dir,
                knobs,
                ladder,
                # Audit the true outcome class (issue #1122): a stock-body
                # crash must not be recorded as a completed run.
                outcome or ("crashed" if crashed else "completed"),
            )
        # Our ladder's verdict outranks a late worker error: once we decided
        # the run is a stall/ceiling timeout, the harness must see exactly
        # the timeout classification it would have produced itself.
        if outcome:
            return AgentResult(
                total_input_tokens=0,
                total_output_tokens=0,
                failure_mode=FailureMode.AGENT_TIMEOUT,
                timestamped_markers=[(0.0, f"agent_timeout({outcome})")],
            )
        if crashed:
            raise box["error"]
        return box.get("result") or AgentResult(
            total_input_tokens=0, total_output_tokens=0
        )

    @staticmethod
    def _tap_pane(session, on: bool) -> None:
        line = (
            f"rm -f {_PROGRESS_LOG}; tmux pipe-pane 'cat >> {_PROGRESS_LOG}'"
            if on
            else "tmux pipe-pane"
        )
        session.send_keys([line, "Enter"], block=False, min_timeout_sec=1.0 if on else 0.0)

    @staticmethod
    def _progress_bytes(session):
        try:
            result = session.container.exec_run(
                ["sh", "-c", f"wc -c < {_PROGRESS_LOG} 2>/dev/null"]
            )
            if result.exit_code == 0:
                return int(result.output.decode(errors="replace").strip() or 0)
        except Exception:
            # Best-effort sample: a broken/wedged container must never kill
            # a healthy run — None keeps the ladder's previous state, and a
            # genuinely dead …

content.text:
        try:
            await self.exec_as_agent(
                environment,
                command=(
                    f"mkdir -p /logs/agent && printf %s {payload} "
                    f"| base64 -d > {_AUDIT_PATH}"
                ),
                timeout_sec=15,
            )
        except Exception:
            pass

    def populate_context_post_run(self, context: AgentContext) -> None:
        """Fold fa's session token accounting into the agent context.

        fa session JSONL assistant records embed
        ``message.usage = {input, output, cacheRead, cacheWrite, ...}``
        (Usage.toJson in lib/src/types.dart); summed across records this is
        the billed usage for the trial. Flat ``inputTokens``-style keys are
        accepted as a fallback for older session shapes.
        """
        sessions_dir = self.logs_dir / "fah-sessions"
        if not sessions_dir.is_dir():
            return
        n_in = n_out = n_cache = 0
        for path in sessions_dir.rglob("*.jsonl"):
            for line in path.read_text(errors="replace").splitlines():
                if '"usage"' not in line and '"inputTokens"' not in line:
                    continue
                try:
                    rec = json.loads(line)
                except json.JSONDecodeError:
                    continue
                message = rec.get("message") or {}
                usage = message.get("usage") or rec
                n_in += usage.get("input") or usage.get("inputTokens") or 0
                n_out += usage.get("output") or usage.get("outputTokens") or 0
                n_cache += (usage.get("cacheRead") or 0) + (
                    usage.get("cacheWrite") or 0
                )
        if n_in or n_out:
            context.n_input_tokens = (context.n_input_tokens or 0) + n_in
            context.n_output_tokens = (context.n_output_tokens or 0) + n_out
            context.n_cache_tokens = (context.n_cache_tokens or 0) + n_cache


def _b64(value: str) -> str:
    return base64.b64encode(value.encode()).decode()

